1	/**
2	 * public-api — Rankora Public REST API
3	 *
4	 * Authenticates requests via API key (Authorization: Bearer rk_live_...)
5	 * Validates key against api_keys table (key_hash = SHA-256 of bearer token).
6	 *
7	 * Routes:
8	 *   GET  /public-api/jobs                     — list jobs for the key owner
9	 *   GET  /public-api/jobs/:id                 — get single job
10	 *   POST /public-api/jobs                     — create a job
11	 *   GET  /public-api/jobs/:id/candidates      — list ranked candidates
12	 *   GET  /public-api/jobs/:id/results         — alias for candidates
13	 */
14	
15	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
16	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
17	
18	const CORS_HEADERS = {
19	  "Access-Control-Allow-Origin": "*",
20	  "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS",
21	  "Access-Control-Allow-Headers": "Authorization, Content-Type",
22	};
23	
24	function json(data: unknown, status = 200): Response {
25	  return new Response(JSON.stringify(data), {
26	    status,
27	    headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
28	  });
29	}
30	
31	function error(message: string, status: number, code?: string): Response {
32	  return json({ error: message, code: code ?? "error" }, status);
33	}
34	
35	/** Convert full API key string → SHA-256 hex digest */
36	async function hashKey(raw: string): Promise<string> {
37	  const encoder = new TextEncoder();
38	  const data = encoder.encode(raw);
39	  const digest = await crypto.subtle.digest("SHA-256", data);
40	  return Array.from(new Uint8Array(digest))
41	    .map((b) => b.toString(16).padStart(2, "0"))
42	    .join("");
43	}
44	
45	serve(async (req: Request) => {
46	  if (req.method === "OPTIONS") {
47	    return new Response(null, { headers: CORS_HEADERS });
48	  }
49	
50	  // ── Auth ─────────────────────────────────────────────────────
51	  const authHeader = req.headers.get("Authorization") ?? "";
52	  const match = authHeader.match(/^Bearer\s+(rk_live_[A-Za-z0-9]+)$/);
53	  if (!match) {
54	    return error(
55	      "Missing or invalid API key. Include: Authorization: Bearer rk_live_...",
56	      401,
57	      "unauthorized"
58	    );
59	  }
60	  const rawKey = match[1];
61	
62	  const supabase = createClient(
63	    Deno.env.get("SUPABASE_URL")!,
64	    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
65	  );
66	
67	  const keyHash = await hashKey(rawKey);
68	  const { data: keyRecord, error: keyErr } = await supabase
69	    .from("api_keys")
70	    .select("id, user_id, revoked")
71	    .eq("key_hash", keyHash)
72	    .single();
73	
74	  if (keyErr || !keyRecord) {
75	    return error("Invalid API key.", 401, "unauthorized");
76	  }
77	  if (keyRecord.revoked) {
78	    return error("This API key has been revoked.", 401, "key_revoked");
79	  }
80	
81	  const userId: string = keyRecord.user_id;
82	
83	  // Update last_used_at (fire-and-forget)
84	  supabase
85	    .from("api_keys")
86	    .update({ last_used_at: new Date().toISOString() })
87	    .eq("id", keyRecord.id)
88	    .then(() => {})
89	    .catch(() => {});
90	
91	  // ── Route ────────────────────────────────────────────────────
92	  const url = new URL(req.url);
93	  // Strip function prefix from path so we route on the logical path
94	  // e.g. /public-api/jobs  or  /jobs (when invoked directly)
95	  const rawPath = url.pathname;
96	  const path = rawPath.replace(/^\/public-api/, "").replace(/^\/functions\/v1\/public-api/, "");
97	
98	  // GET /jobs
99	  if (req.method === "GET" && path === "/jobs") {
100	    const limit = Math.min(Number(url.searchParams.get("limit") ?? 20), 100);
101	    const offset = Number(url.searchParams.get("offset") ?? 0);
102	    const { data, error: dbErr } = await supabase
103	      .from("jobs")
104	      .select("id, title, status, created_at, jd_analysis_json")
105	      .eq("user_id", userId)
106	      .order("created_at", { ascending: false })
107	      .range(offset, offset + limit - 1);
108	    if (dbErr) return error("Failed to fetch jobs.", 500);
109	    return json({ data, offset, limit });
110	  }
111	
112	  // POST /jobs — create job
113	  if (req.method === "POST" && path === "/jobs") {
114	    let body: Record<string, unknown>;
115	    try {
116	      body = await req.json();
117	    } catch {
118	      return error("Invalid JSON body.", 400, "bad_request");
119	    }
120	    const title = typeof body.title === "string" ? body.title.trim() : null;
121	    const job_description = typeof body.job_description === "string" ? body.job_description.trim() : "";
122	    if (!job_description) {
123	      return error("job_description is required.", 400, "validation_error");
124	    }
125	    const { data, error: dbErr } = await supabase
126	      .from("jobs")
127	      .insert({ user_id: userId, title, job_description, status: "pending" })
128	      .select("id, title, status, created_at")
129	      .single();
130	    if (dbErr || !data) return error("Failed to create job.", 500);
131	    return json(data, 201);
132	  }
133	
134	  // Match /jobs/:id  or  /jobs/:id/candidates  or  /jobs/:id/results
135	  const jobIdMatch = path.match(/^\/jobs\/([0-9a-f-]{36})(\/candidates|\/results)?$/i);
136	  if (!jobIdMatch) {
137	    return error(
138	      `Route not found: ${req.method} ${path}`,
139	      404,
140	      "not_found"
141	    );
142	  }
143	
144	  const jobId = jobIdMatch[1];
145	  const subRoute = jobIdMatch[2] ?? "";
146	
147	  // Verify ownership
148	  const { data: job, error: jobErr } = await supabase
149	    .from("jobs")
150	    .select("id, title, status, created_at, job_description, jd_analysis_json")
151	    .eq("id", jobId)
152	    .eq("user_id", userId)
153	    .single();
154	  if (jobErr || !job) {
155	    return error("Job not found or access denied.", 404, "not_found");
156	  }
157	
158	  // GET /jobs/:id
159	  if (req.method === "GET" && subRoute === "") {
160	    return json(job);
161	  }
162	
163	  // GET /jobs/:id/candidates  or  /jobs/:id/results
164	  if (req.method === "GET" && (subRoute === "/candidates" || subRoute === "/results")) {
165	    const { data: resumes } = await supabase
166	      .from("resumes")
167	      .select("id, filename, candidate_name, created_at")
168	      .eq("job_id", jobId);
169	
170	    const resumeIds = (resumes ?? []).map((r: any) => r.id);
171	    if (resumeIds.length === 0) return json({ data: [], job_id: jobId });
172	
173	    const { data: results } = await supabase
174	      .from("results")
175	      .select("id, resume_id, overall_score, missing_skills, strengths_json, gaps_json, hard_fit, confidence, matched_must_haves, missing_must_haves")
176	      .in("resume_id", resumeIds)
177	      .order("overall_score", { ascending: false });
178	
179	    const resumeMap = new Map((resumes ?? []).map((r: any) => [r.id, r]));
180	    const candidates = (results ?? []).map((r: any) => {
181	      const resume = resumeMap.get(r.resume_id);
182	      return {
183	        ...r,
184	        filename: resume?.filename ?? "Unknown",
185	        candidate_name: resume?.candidate_name ?? null,
186	        uploaded_at: resume?.created_at ?? null,
187	      };
188	    });
189	
190	    return json({ data: candidates, job_id: jobId, total: candidates.length });
191	  }
192	
193	  return error(`Method not allowed: ${req.method}`, 405, "method_not_allowed");
194	});
