/**
 * Try each selector in order, return trimmed text of first match or null.
 */
function trySelectors(selectors) {
  for (const sel of selectors) {
    try {
      const el = document.querySelector(sel);
      if (el) {
        const text = el.innerText || el.textContent || '';
        const trimmed = text.trim().replace(/\s+/g, ' ');
        if (trimmed) return trimmed;
      }
    } catch (_) {
      // Ignore invalid selectors — continue trying
    }
  }
  return null;
}

/**
 * Try each selector, return array of trimmed text values.
 */
function trySelectorsAll(selectors) {
  for (const sel of selectors) {
    try {
      const els = document.querySelectorAll(sel);
      if (els.length > 0) {
        const values = Array.from(els)
          .map((el) => (el.innerText || el.textContent || '').trim().replace(/\s+/g, ' '))
          .filter(Boolean);
        if (values.length > 0) return values;
      }
    } catch (_) {
      // Ignore
    }
  }
  return [];
}

