/**
 * extension-capture — Rankora Chrome Extension Capture API
 *
 * Accepts candidate profiles captured from LinkedIn / GitHub via the
 * Rankora Chrome Extension and stores them as resumes (candidate profiles)
 * in the user's talent pool.
 *
 * Auth: API key (Authorization: Bearer rk_live_...)
 *       Same validation as public-api — key_hash lookup in api_keys table.
 *
 * Routes:
 *   POST /extension-capture         — capture a candidate profile
 *   POST /extension-capture/verify  — verify API key only (used by popup on login)
 *
 * CORS: * (required for chrome-extension:// origin)
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";

// ─── CORS ─────────────────────────────────────────────────────────────────────

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Authorization, Content-Type",
};

// ─── Response helpers ─────────────────────────────────────────────────────────

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
  });
}

function error(message: string, status: number, code = "error"): Response {
  return json({ error: message, code }, status);
}

// ─── API key auth (mirrors public-api pattern exactly) ────────────────────────

async function hashKey(raw: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(raw);
  const digest = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

interface AuthResult {
  userId: string;
  keyId: string;
}

async function authenticateRequest(
  req: Request,
  supabase: ReturnType<typeof createClient>
): Promise<{ auth: AuthResult | null; errorResponse: Response | null }> {
  const authHeader = req.headers.get("Authorization") ?? "";
  const match = authHeader.match(/^Bearer\s+(rk_live_[A-Za-z0-9]+)$/);

  if (!match) {
    return {
      auth: null,
      errorResponse: error(
        "Missing or invalid API key. Include: Authorization: Bearer rk_live_...",
        401,
        "unauthorized"
      ),
    };
  }

  const rawKey = match[1];
  const keyHash = await hashKey(rawKey);

  const { data: keyRecord, error: keyErr } = await supabase
    .from("api_keys")
    .select("id, user_id, revoked")
    .eq("key_hash", keyHash)
    .single();

  if (keyErr || !keyRecord) {
    return { auth: null, errorResponse: error("Invalid API key.", 401, "unauthorized") };
  }

  if (keyRecord.revoked) {
    return {
      auth: null,
      errorResponse: error("This API key has been revoked.", 401, "key_revoked"),
    };
  }

  // Update last_used_at (fire-and-forget)
  supabase
    .from("api_keys")
    .update({ last_used_at: new Date().toISOString() })
    .eq("id", keyRecord.id)
    .then(() => {})
    .catch(() => {});

  return { auth: { userId: keyRecord.user_id, keyId: keyRecord.id }, errorResponse: null };
}

// ─── Input validation ─────────────────────────────────────────────────────────

interface CaptureBody {
  name?: string;
  title?: string;
  company?: string;
  location?: string;
  bio?: string;
  profile_url?: string;
  source?: string;
}

function validateBody(body: unknown): { data: CaptureBody; validationError: string | null } {
  if (!body || typeof body !== "object") {
    return { data: {}, validationError: "Request body must be a JSON object." };
  }

  const b = body as Record<string, unknown>;

  const name = typeof b.name === "string" ? b.name.trim().slice(0, 255) : null;
  if (!name) {
    return { data: {}, validationError: "name is required." };
  }

  const profileUrl = typeof b.profile_url === "string" ? b.profile_url.trim().slice(0, 2000) : null;
  if (!profileUrl) {
    return { data: {}, validationError: "profile_url is required." };
  }

  // Validate profile_url is from a supported domain
  const allowedDomains = ["linkedin.com", "github.com"];
  const urlLower = profileUrl.toLowerCase();
  const isAllowed = allowedDomains.some((d) => urlLower.includes(d));
  if (!isAllowed) {
    return { data: {}, validationError: "profile_url must be from linkedin.com or github.com." };
  }

  const source = typeof b.source === "string" ? b.source : "other";
  const validSources = ["linkedin", "github", "other"];
  const resolvedSource = validSources.includes(source) ? source : "other";

  return {
    data: {
      name,
      title: typeof b.title === "string" ? b.title.trim().slice(0, 255) : undefined,
      company: typeof b.company === "string" ? b.company.trim().slice(0, 255) : undefined,
      location: typeof b.location === "string" ? b.location.trim().slice(0, 255) : undefined,
      bio: typeof b.bio === "string" ? b.bio.trim().slice(0, 2000) : undefined,
      profile_url: profileUrl,
      source: resolvedSource,
    },
    validationError: null,
  };
}

// ─── Main handler ─────────────────────────────────────────────────────────────

serve(async (req: Request) => {
  // Preflight
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  // Only accept POST
  if (req.method !== "POST") {
    return error("Method not allowed.", 405, "method_not_allowed");
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  // Auth
  const { auth, errorResponse } = await authenticateRequest(req, supabase);
  if (!auth) return errorResponse!;

  const { userId } = auth;

  // Route: /verify — just returns 200 if auth passed
  const url = new URL(req.url);
  const path = url.pathname.replace(/\/functions\/v1\/extension-capture/, "").replace(/^\/extension-capture/, "");

  if (path === "/verify" || path === "/verify/") {
    return json({ ok: true, user_id: userId });
  }

  // Route: POST / — capture candidate
  let rawBody: unknown;
  try {
    rawBody = await req.json();
  } catch {
    return error("Invalid JSON body.", 400, "bad_request");
  }

  const { data: captureData, validationError } = validateBody(rawBody);
  if (validationError) {
    return error(validationError, 400, "validation_error");
  }

  // ── Duplicate check ─────────────────────────────────────────────────────────
  // Check if this profile_url already exists in resumes for this user
  // (via jobs owned by user or via existing candidate profile resumes)
  const { data: existing } = await supabase
    .from("resumes")
    .select("id, candidate_name")
    .filter("parsed_json->>profile_url", "eq", captureData.profile_url)
    .limit(1);

  // Check if any of the existing resumes belong to this user's jobs
  if (existing && existing.length > 0) {
    const resumeId = existing[0].id;
    const { data: ownerCheck } = await supabase
      .from("resumes")
      .select("id, jobs!inner(user_id)")
      .eq("id", resumeId)
      .eq("jobs.user_id", userId)
      .limit(1);

    if (ownerCheck && ownerCheck.length > 0) {
      return json(
        {
          success: false,
          error: "This candidate is already in your talent pool.",
          code: "duplicate",
          candidate_id: resumeId,
        },
        409
      );
    }
  }

  // ── Create job for candidate pool (use sentinel job or create a "Talent Pool" job) ──
  // Look for an existing talent pool job for this user
  const TALENT_POOL_TITLE = "__rankora_talent_pool__";

  let { data: poolJob } = await supabase
    .from("jobs")
    .select("id")
    .eq("user_id", userId)
    .eq("title", TALENT_POOL_TITLE)
    .limit(1)
    .single();

  if (!poolJob) {
    // Create the sentinel talent pool job (hidden from UI via title prefix)
    const { data: newJob, error: jobErr } = await supabase
      .from("jobs")
      .insert({
        user_id: userId,
        title: TALENT_POOL_TITLE,
        job_description: "Chrome extension talent pool capture job. Do not delete.",
        status: "completed",
      })
      .select("id")
      .single();

    if (jobErr || !newJob) {
      console.error("Failed to create talent pool job:", jobErr);
      return error("Failed to initialize talent pool. Please try again.", 500, "internal_error");
    }

    poolJob = newJob;
  }

  // ── Insert resume record ────────────────────────────────────────────────────
  const parsed_json = {
    profile_url: captureData.profile_url,
    source: captureData.source,
    title: captureData.title ?? null,
    company: captureData.company ?? null,
    location: captureData.location ?? null,
    bio: captureData.bio ?? null,
    captured_at: new Date().toISOString(),
    captured_via: "chrome_extension",
  };

  const { data: resume, error: resumeErr } = await supabase
    .from("resumes")
    .insert({
      job_id: poolJob.id,
      candidate_name: captureData.name!,
      filename: `${captureData.source}_profile.html`,
      file_path: captureData.profile_url!,
      status: "done",
      parsed_json,
      parsed_text: [
        captureData.name,
        captureData.title,
        captureData.company,
        captureData.location,
        captureData.bio,
      ]
        .filter(Boolean)
        .join("\n"),
    })
    .select("id, candidate_name")
    .single();

  if (resumeErr || !resume) {
    console.error("Failed to insert resume:", resumeErr);
    return error("Failed to capture candidate. Please try again.", 500, "internal_error");
  }

  return json(
    {
      success: true,
      candidate_id: resume.id,
      candidate_name: resume.candidate_name,
      message: `${captureData.name} has been added to your talent pool.`,
    },
    201
  );
});

